DROP TABLE IF EXISTS `management`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `management` (
  `management_id` int NOT NULL AUTO_INCREMENT,
  `mamber_id` varchar(100) NOT NULL,
  `company_name` varchar(100) NOT NULL,
  `member_name` varchar(100) NOT NULL,
  `company_address` varchar(100) NOT NULL,
  `father_name` varchar(100) NOT NULL,
  `state` varchar(100) NOT NULL,
  `member_photo` varchar(100) NOT NULL,
  `city` varchar(100) NOT NULL,
  `residential_address` varchar(100) NOT NULL,
  `company_tel` varchar(50) NOT NULL,
  `mobile_no` varchar(50) NOT NULL,
  `fax` varchar(50) NOT NULL,
  `residential_telephone` varchar(50) NOT NULL,
  `date_of_joining` varchar(100) NOT NULL,
  `designation` varchar(100) NOT NULL,
  `Submit_Date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `activeStatus` varchar(50) DEFAULT NULL,
  `mana_desigstatus` int DEFAULT NULL,
  `pancardno` varchar(100) NOT NULL,
  `adharcardno` varchar(100) NOT NULL,
  PRIMARY KEY (`management_id`),
  UNIQUE KEY `management_id` (`management_id`)
) ENGINE=InnoDB AUTO_INCREMENT=464 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

